import { chromium } from 'playwright';
const browser=await chromium.launch({channel:'chrome',headless:true,args:['--use-fake-ui-for-media-stream','--use-fake-device-for-media-stream','--autoplay-policy=no-user-gesture-required']});
const base='http://127.0.0.1:4173/calculator-v42.html';
async function makePhone(number){const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true,permissions:['microphone','camera']});await context.addInitScript(n=>{localStorage.setItem('calculator-number',n);localStorage.setItem('main-code','5963')},number);const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(String(e)));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});await page.goto(base,{waitUntil:'load',timeout:25000});for(const d of ['5','9','6','3'])await page.locator(`#calc [data-v="${d}"]`).click();await page.locator('#calc [data-a="eq"]').click();await page.locator('.calculator-phone-launch').first().waitFor({state:'visible',timeout:10000});await page.waitForTimeout(1200);return{context,page,errors}}
const A=await makePhone('111-111-1111'),B=await makePhone('222-222-2222');
await A.page.locator('.calculator-phone-launch').first().click({timeout:3000});await A.page.locator('#app.screen.active .phone-app-page').waitFor({state:'visible',timeout:3000});const keys=await A.page.locator('.dialpad .dial-key').allTextContents();console.log('DIAL_KEYS',JSON.stringify(keys));if(keys.length<10)throw new Error('Dialpad did not render');const two=A.page.locator('.dialpad .dial-key').nth(1);for(let i=0;i<10;i++)await two.evaluate(el=>el.click());const dial=(await A.page.locator('.dial-number').textContent())?.trim();if(dial!=='222-222-2222')throw new Error('Caller dialpad produced '+dial);
await A.page.locator('.dial-call').evaluate(el=>el.click());await B.page.locator('#calcCallOverlay #accept').waitFor({state:'visible',timeout:10000});const incomingText=(await B.page.locator('#calcCallOverlay').textContent())||'';console.log('INCOMING_OVERLAY',incomingText.replace(/\s+/g,' ').trim());if(!incomingText.includes('111-111-1111'))throw new Error('Incoming call did not show caller number');const ringResponsive=await B.page.evaluate(()=>new Promise(r=>setTimeout(()=>r(true),700)));if(!ringResponsive)throw new Error('Incoming ringtone blocked UI');await B.page.locator('#calcCallOverlay #accept').click({timeout:3000});
await A.page.waitForFunction(()=>document.querySelector('#callStatus')?.textContent==='Connected',{timeout:18000}).catch(()=>{});const aStatus=(await A.page.locator('#callStatus').textContent().catch(()=>''))||'';const bOverlay=await B.page.locator('#calcCallOverlay').count();console.log('CALLER_STATUS',aStatus,'CALLEE_OVERLAY',bOverlay);if(!bOverlay)throw new Error('Callee call screen disappeared after answer');const endB=B.page.locator('#calcCallOverlay #callEnd').first();if(await endB.count())await endB.evaluate(el=>el.click());else{const endA=A.page.locator('#calcCallOverlay #callEnd').first();if(await endA.count())await endA.evaluate(el=>el.click());else throw new Error('No hangup button after answer')}
await A.page.waitForFunction(()=>!document.getElementById('calcCallOverlay'),{timeout:8000});await B.page.waitForFunction(()=>!document.getElementById('calcCallOverlay'),{timeout:8000});if(A.errors.length||B.errors.length)throw new Error('Browser errors: '+[...A.errors,...B.errors].join(' | '));console.log('CALCULATOR_REAL_TWO_PHONE_CALL_TEST_PASS');await A.context.close();await B.context.close();await browser.close();
